<?php
$page_title='รายละเอียดร้านค้า';require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();if(!$db)exit('Database unavailable');
$sellerId=max(0,(int)($_GET['id']??$_POST['seller_id']??0));$message=$error='';$load=$db->prepare('SELECT sp.*,u.username,u.email,u.full_name,c.name category_name FROM seller_profiles sp JOIN users u ON u.id=sp.user_id JOIN categories c ON c.id=sp.primary_category_id WHERE sp.user_id=?');$load->execute([$sellerId]);$store=$load->fetch();if(!$store){http_response_code(404);exit('ไม่พบร้านค้า');}
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);$action=(string)($_POST['action']??'');$note=trim((string)($_POST['note']??''));try{
 if(in_array($action,['activate','suspend','close'],true)){$status=['activate'=>'active','suspend'=>'suspended','close'=>'closed'][$action];if($status!=='active'&&mb_strlen($note)<5)throw new RuntimeException('กรุณาระบุเหตุผลอย่างน้อย 5 ตัวอักษร');$db->prepare("UPDATE seller_profiles SET store_status=?,suspension_reason=?,suspended_at=IF(?='active',NULL,NOW()),suspended_by=IF(?='active',NULL,?) WHERE user_id=? AND status='approved'")->execute([$status,$status==='active'?null:$note,$status,$status,(int)$_SESSION['user_id'],$sellerId]);auditLog($db,'seller.store.'.$status,'seller_store',$sellerId,['status'=>$store['store_status']],['status'=>$status,'reason'=>$note]);createNotification($db,$sellerId,'seller','สถานะร้านค้าถูกอัปเดต',$status==='active'?'ร้านกลับมาเปิดใช้งานแล้ว':$note,BASE_URL.'my-store.php');$message='อัปเดตสถานะร้านแล้ว';}
 elseif($action==='permissions'){$values=[isset($_POST['products'])?1:0,isset($_POST['orders'])?1:0,isset($_POST['payout'])?1:0];$db->prepare('UPDATE seller_profiles SET product_submission_enabled=?,order_processing_enabled=?,payout_enabled=? WHERE user_id=?')->execute([...$values,$sellerId]);auditLog($db,'seller.permissions.update','seller_store',$sellerId,null,$values);createNotification($db,$sellerId,'seller','สิทธิ์ร้านค้าถูกอัปเดต',$note?:'โปรดตรวจสอบสิทธิ์ในศูนย์ผู้ขาย',BASE_URL.'seller-dashboard.php');$message='บันทึกสิทธิ์แล้ว';}
 elseif($action==='product'){$productId=(int)($_POST['product_id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['approved','rejected'],true))throw new RuntimeException('สถานะไม่ถูกต้อง');$stmt=$db->prepare('UPDATE products SET approval_status=?,admin_note=? WHERE id=? AND seller_id=?');$stmt->execute([$status,$note?:null,$productId,$sellerId]);if(!$stmt->rowCount())throw new RuntimeException('ไม่พบสินค้า');auditLog($db,'seller.product.'.$status,'product',$productId,null,['seller_id'=>$sellerId,'note'=>$note]);createNotification($db,$sellerId,'seller','ผลตรวจสอบสินค้า',$note?:'สถานะสินค้าเปลี่ยนเป็น '.$status,BASE_URL.'seller-dashboard.php');$message='อัปเดตสินค้าแล้ว';}
 elseif($action==='notify'){if(mb_strlen($note)<3)throw new RuntimeException('กรุณากรอกข้อความ');createNotification($db,$sellerId,'seller','ข้อความจากผู้ดูแลร้านค้า',$note,BASE_URL.'notifications.php');auditLog($db,'seller.message','seller_store',$sellerId,null,['message'=>$note]);$message='ส่งข้อความแล้ว';}else throw new RuntimeException('คำสั่งไม่ถูกต้อง');$load->execute([$sellerId]);$store=$load->fetch();
}catch(Throwable $e){$error=$e->getMessage();}}
$q=$db->prepare("SELECT p.*,c.name category_name,COALESCE(SUM(oi.quantity),0) sold FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN order_items oi ON oi.product_id=p.id WHERE p.seller_id=? GROUP BY p.id,c.name ORDER BY p.created_at DESC");$q->execute([$sellerId]);$products=$q->fetchAll();
$q=$db->prepare("SELECT o.id,o.order_no,o.created_at,o.payment_status,SUM(oi.subtotal) total,GROUP_CONCAT(CONCAT(oi.product_name,' x',oi.quantity) SEPARATOR ', ') items,MAX(f.status) fulfillment FROM orders o JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id LEFT JOIN order_fulfillments f ON f.order_id=o.id AND f.seller_id=? WHERE p.seller_id=? GROUP BY o.id ORDER BY o.created_at DESC LIMIT 100");$q->execute([$sellerId,$sellerId]);$orders=$q->fetchAll();
$q=$db->prepare("SELECT COALESCE(SUM(oi.subtotal),0) gross,COUNT(DISTINCT o.id) orders FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN products p ON p.id=oi.product_id WHERE p.seller_id=? AND o.order_status<>'cancelled'");$q->execute([$sellerId]);$finance=$q->fetch();
$q=$db->prepare('SELECT COUNT(*) reviews,COALESCE(AVG(r.rating),0) rating FROM product_reviews r JOIN products p ON p.id=r.product_id WHERE p.seller_id=?');$q->execute([$sellerId]);$review=$q->fetch();$q=$db->prepare('SELECT COUNT(DISTINCT rr.id) FROM return_requests rr JOIN order_items oi ON oi.order_id=rr.order_id JOIN products p ON p.id=oi.product_id WHERE p.seller_id=?');$q->execute([$sellerId]);$returns=(int)$q->fetchColumn();
$q=$db->prepare('SELECT r.rating,r.comment,r.created_at,p.name product_name,u.username FROM product_reviews r JOIN products p ON p.id=r.product_id JOIN users u ON u.id=r.user_id WHERE p.seller_id=? ORDER BY r.created_at DESC LIMIT 50');$q->execute([$sellerId]);$reviewRows=$q->fetchAll();$q=$db->prepare('SELECT DISTINCT rr.id,rr.status,rr.reason,rr.created_at,o.order_no FROM return_requests rr JOIN orders o ON o.id=rr.order_id JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id WHERE p.seller_id=? ORDER BY rr.created_at DESC LIMIT 50');$q->execute([$sellerId]);$returnRows=$q->fetchAll();$q=$db->prepare('SELECT DISTINCT st.id,st.ticket_no,st.subject,st.priority,st.status,st.created_at FROM support_tickets st JOIN orders o ON o.id=st.order_id JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id WHERE p.seller_id=? ORDER BY st.created_at DESC LIMIT 50');$q->execute([$sellerId]);$tickets=$q->fetchAll();
$q=$db->prepare('SELECT * FROM seller_payout_requests WHERE seller_id=? ORDER BY requested_at DESC LIMIT 100');$q->execute([$sellerId]);$payouts=$q->fetchAll();$q=$db->prepare('SELECT * FROM security_events WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([$sellerId]);$events=$q->fetchAll();$risk=0;foreach($events as $e)$risk=max($risk,(int)$e['risk_score']);$q=$db->prepare("SELECT a.*,u.username actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id WHERE a.entity_type='seller_store' AND a.entity_id=? ORDER BY a.created_at DESC LIMIT 100");$q->execute([$sellerId]);$audits=$q->fetchAll();
function maskStoreAccount($v):string{$v=trim((string)$v);return mb_strlen($v)<=4?$v:str_repeat('•',mb_strlen($v)-4).mb_substr($v,-4);}require_once __DIR__.'/../includes/admin_header.php';?>
