เงิน</label><input name="note" placeholder="ข้อความแจ้งผู้ขาย"><button class="btn btn-primary" name="action" value="permissions">บันทึกสิทธิ์</button></form><form method="post" class="admin-form-grid"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="seller_id" value="<?php echo $sellerId;?>"><textarea class="full" name="note" required maxlength="500" placeholder="ข้อความถึงผู้ขาย"></textarea><button class="btn btn-outline full" name="action" value="notify">ส่ง Notification</button></form></div></div></section>
